#!/usr/bin/env node
// Adopts the project settings of a fresh Unity Hub project into this repo.
//
// Why: ProjectSettings/ and the URP 2D render-pipeline assets must be generated by the exact Unity
// version you use. Create an empty project from Unity Hub's "Universal 2D" template, then run:
//
//   node Tools/setup/adopt-unity-project.mjs <path-to-that-project> [--force] [--dry-run]
//
// It copies ProjectSettings/, the URP assets in Assets/Settings/, and Packages/manifest.json,
// then merges in the packages from template-packages.json (adds missing ones, never downgrades).
// Afterwards open this repo folder in Unity and run: Template > Apply Project Setup.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const args = process.argv.slice(2);
const source = args.find((a) => !a.startsWith('--'));
const force = args.includes('--force');
const dryRun = args.includes('--dry-run');

function fail(message) {
  console.error(`✗ ${message}`);
  process.exit(1);
}

if (!source) {
  fail('Usage: node Tools/setup/adopt-unity-project.mjs <path-to-unity-hub-project> [--force] [--dry-run]');
}

const src = path.resolve(source);
for (const required of ['ProjectSettings/ProjectVersion.txt', 'Packages/manifest.json']) {
  if (!fs.existsSync(path.join(src, required))) {
    fail(`${src} doesn't look like a Unity project (missing ${required}). Create it from Unity Hub first.`);
  }
}

if (fs.existsSync(path.join(repo, 'ProjectSettings')) && !force) {
  fail('This repo already has ProjectSettings/. Re-run with --force to overwrite them.');
}

const actions = [];

function copyRecursive(from, to) {
  const stat = fs.statSync(from);
  if (stat.isDirectory()) {
    if (!dryRun) fs.mkdirSync(to, { recursive: true });
    for (const entry of fs.readdirSync(from)) copyRecursive(path.join(from, entry), path.join(to, entry));
  } else {
    if (!dryRun) {
      fs.mkdirSync(path.dirname(to), { recursive: true });
      fs.copyFileSync(from, to);
    }
    actions.push(path.relative(repo, to));
  }
}

function copyIfExists(relative) {
  const from = path.join(src, relative);
  if (fs.existsSync(from)) copyRecursive(from, path.join(repo, relative));
}

// 1. Project settings generated by your Unity version.
copyRecursive(path.join(src, 'ProjectSettings'), path.join(repo, 'ProjectSettings'));

// 2. Render-pipeline assets and other root-level assets the template references (skip samples/tutorials).
copyIfExists('Assets/Settings');
copyIfExists('Assets/Settings.meta');
const skipRootAssets = new Set(['Readme.asset', 'Readme.asset.meta']);
for (const entry of fs.readdirSync(path.join(src, 'Assets'))) {
  const full = path.join(src, 'Assets', entry);
  if (fs.statSync(full).isFile() && !skipRootAssets.has(entry) && /\.(asset|inputactions)(\.meta)?$/.test(entry)) {
    copyRecursive(full, path.join(repo, 'Assets', entry));
  }
}

// 3. Package manifest: start from Unity's, merge in what the template needs.
const manifest = JSON.parse(fs.readFileSync(path.join(src, 'Packages/manifest.json'), 'utf8'));
const wanted = JSON.parse(fs.readFileSync(path.join(repo, 'Tools/setup/template-packages.json'), 'utf8'));

const semver = /^\d+\.\d+\.\d+$/;
const newer = (a, b) => {
  const pa = a.split('.').map(Number);
  const pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) if (pa[i] !== pb[i]) return pa[i] > pb[i];
  return false;
};

manifest.dependencies ??= {};
const packageChanges = [];
for (const [name, version] of Object.entries(wanted.dependencies)) {
  const current = manifest.dependencies[name];
  if (current === undefined) {
    manifest.dependencies[name] = version;
    packageChanges.push(`+ ${name} ${version}`);
  } else if (semver.test(current) && semver.test(version) && newer(version, current)) {
    manifest.dependencies[name] = version;
    packageChanges.push(`↑ ${name} ${current} → ${version}`);
  }
}

manifest.scopedRegistries ??= [];
for (const registry of wanted.scopedRegistries) {
  const existing = manifest.scopedRegistries.find((r) => r.url === registry.url);
  if (!existing) {
    manifest.scopedRegistries.push(registry);
    packageChanges.push(`+ registry ${registry.url} (${registry.scopes.join(', ')})`);
  } else {
    for (const scope of registry.scopes) {
      if (!existing.scopes.includes(scope)) {
        existing.scopes.push(scope);
        packageChanges.push(`+ scope ${scope} on ${registry.url}`);
      }
    }
  }
}

manifest.dependencies = Object.fromEntries(Object.entries(manifest.dependencies).sort(([a], [b]) => a.localeCompare(b)));
if (!dryRun) {
  fs.mkdirSync(path.join(repo, 'Packages'), { recursive: true });
  fs.writeFileSync(path.join(repo, 'Packages/manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
}

const version = fs.readFileSync(path.join(src, 'ProjectSettings/ProjectVersion.txt'), 'utf8').match(/m_EditorVersion: (.+)/)?.[1];
console.log(`${dryRun ? '[dry run] ' : ''}Adopted Unity ${version} project settings from ${src}`);
console.log(`  ${actions.length} files copied (ProjectSettings, URP assets)`);
console.log(`  Packages/manifest.json: ${packageChanges.length ? '\n    ' + packageChanges.join('\n    ') : 'already had everything'}`);
console.log('\nNext: open this folder in Unity Hub (Add → project from disk), wait for packages to import,');
console.log('then run the menu Template > Apply Project Setup and press Play in Assets/_Project/Scenes/Boot.unity.');
